## Description

<!-- Provide a brief description of the changes in this PR -->
Convert tool-output to custom ui to support custom AI sdk tool support.

Supports
```
export const weatherTool = createTool({
  id: "get-weather",
  description: "Get current weather for a location",
  inputSchema: z.object({
    location: z.string().describe("City name"),
  }),
  outputSchema: z.object({
    temperature: z.number(),
    feelsLike: z.number(),
    humidity: z.number(),
    windSpeed: z.number(),
    windGust: z.number(),
    conditions: z.string(),
    location: z.string(),
  }),
  execute: async ({ context, writer, runId }, { toolCallId }) => {
    console.log("runId", runId);
    // update display
    writer?.write({
      type: "data-weather",
      id: toolCallId,
      data: { city: context.location, status: "loading" },
    });

    const result = await getWeather(context.location);

    // update display
    writer?.write({
      type: "data-weather",
      id: toolCallId,
      data: {
        city: context.location,
        weather: {
          ...result,
          unit: "celsius",
        },
        status: "success",
      },
    });

    return result;
  },
});
```

https://ai-sdk.dev/docs/ai-sdk-ui/streaming-data

